CREATE OR REPLACE FUNCTION public.can_read_shared_order(_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM public.shared_orders WHERE id=_id AND buyer_id=auth.uid()) OR public.has_role(auth.uid(),'admin') OR (public.account_activity_allowed() AND EXISTS(SELECT 1 FROM public.shared_order_items i JOIN public.user_roles r ON r.vendor_id=i.vendor_id WHERE i.order_id=_id AND r.user_id=auth.uid() AND r.role='vendor'))) $$;
CREATE POLICY "Restricted vendors cannot read customer items" ON public.shared_order_items AS RESTRICTIVE FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.shared_orders o WHERE o.id=order_id AND o.buyer_id=auth.uid()) OR public.account_activity_allowed());
CREATE POLICY "Restricted vendors cannot read customer contacts" ON public.shared_orders AS RESTRICTIVE FOR SELECT TO authenticated USING (buyer_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.account_activity_allowed());